def bbox(grid):
    """The (top, left, bottom, right) bounding box of all nonzero cells, or None if empty."""
    cs = [(i, j) for i, r in enumerate(grid) for j, v in enumerate(r) if v]
    if not cs:
        return None
    return (min(i for i, _ in cs), min(j for _, j in cs), max(i for i, _ in cs), max(j for _, j in cs))

def subgrid(grid, box):
    """The subgrid of grid cut out by a (top, left, bottom, right) box, inclusive."""
    top, left, bot, right = box
    return [row[left:right + 1] for row in grid[top:bot + 1]]

def center_color(grid, box=None):
    """The color at the center of the grid's (or box's) bounding box."""
    top, left, bot, right = box if box else bbox(grid)
    return grid[(top + bot) // 2][(left + right) // 2]

def pow2_floor(n):
    """The largest power of two not exceeding n (at least 1)."""
    p = 1
    while p * 2 <= n:
        p *= 2
    return p

def inner_block(grid, box=None):
    """(height, width) of the center-colored block inside the bounding box."""
    top, left, bot, right = box if box else bbox(grid)
    c = center_color(grid, box)
    cs = [(i, j) for i in range(top, bot + 1) for j in range(left, right + 1) if grid[i][j] == c]
